package codegen

import (
	"bytes"
	"errors"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/RomansWorks/terraform-provider-telnyx/internal/engine"
)

// Marker starts every generated file; stale files carrying it are removed.
const Marker = "// Code generated by cmd/codegen. DO NOT EDIT."

var initialisms = map[string]string{
	"ai": "AI", "api": "API", "id": "ID", "mcp": "MCP", "url": "URL", "sip": "SIP",
	"sms": "SMS", "mms": "MMS", "dtmf": "DTMF", "fqdn": "FQDN", "ip": "IP", "tts": "TTS",
}

// GoName returns the exported Go name for a Terraform type, such as
// AIAssistant for telnyx_ai_assistant.
func GoName(typeName string) string {
	var b strings.Builder
	for _, part := range strings.Split(strings.TrimPrefix(typeName, "telnyx_"), "_") {
		if up, ok := initialisms[part]; ok {
			b.WriteString(up)
		} else if part != "" {
			b.WriteString(strings.ToUpper(part[:1]) + part[1:])
		}
	}
	return b.String()
}

var kindNames = map[engine.Kind]string{
	engine.KindString: "engine.KindString",
	engine.KindInt:    "engine.KindInt",
	engine.KindFloat:  "engine.KindFloat",
	engine.KindBool:   "engine.KindBool",
	engine.KindJSON:   "engine.KindJSON",
	engine.KindList:   "engine.KindList",
	engine.KindSet:    "engine.KindSet",
	engine.KindObject: "engine.KindObject",
}

// EmitResource renders one descriptor as a Go source file.
func EmitResource(pkg string, r *engine.Resource, source string) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s\n// Source: %s\n\n", Marker, source)
	fmt.Fprintf(&b, "package %s\n\n", pkg)
	b.WriteString("import \"github.com/RomansWorks/terraform-provider-telnyx/internal/engine\"\n\n")
	name := GoName(r.TypeName)
	fmt.Fprintf(&b, "// %s returns the descriptor of %s.\n", name, r.TypeName)
	fmt.Fprintf(&b, "func %s() *engine.Resource {\n\treturn &engine.Resource{\n", name)
	field(&b, "TypeName", strconv.Quote(r.TypeName))
	field(&b, "Description", strconv.Quote(r.Description))
	for _, o := range []struct {
		name string
		op   *engine.Op
	}{{"Create", r.Create}, {"Read", r.Read}, {"Update", r.Update}, {"Delete", r.Delete}} {
		if o.op != nil {
			field(&b, o.name, opLiteral(o.op))
		}
	}
	if rf := r.ReadFrom; rf != nil {
		field(&b, "ReadFrom", fmt.Sprintf("&engine.ReadFrom{Op: %s, Field: %q, Key: %q}", opLiteral(rf.Op), rf.Field, rf.Key))
	}
	if len(r.Updates) > 0 {
		b.WriteString("Updates: []engine.ExtraUpdate{\n")
		for _, u := range r.Updates {
			fmt.Fprintf(&b, "{Op: %s, ", opLiteral(u.Op))
			if u.Clear != nil {
				fmt.Fprintf(&b, "Clear: %s, ", opLiteral(u.Clear))
			}
			fmt.Fprintf(&b, "Attrs: %s},\n", quoteList(u.Attrs))
		}
		b.WriteString("},\n")
	}
	field(&b, "IDAttr", strconv.Quote(r.IDAttr))
	field(&b, "Import", quoteList(r.Import))
	if len(r.ExactlyOne) > 0 {
		parts := make([]string, len(r.ExactlyOne))
		for i, g := range r.ExactlyOne {
			parts[i] = quoteList(g)
		}
		field(&b, "ExactlyOne", "[][]string{"+strings.Join(parts, ", ")+"}")
	}
	if r.DeleteWarning != "" {
		field(&b, "DeleteWarning", strconv.Quote(r.DeleteWarning))
	}
	if r.Timeouts {
		field(&b, "Timeouts", "true")
	}
	if r.DataSource {
		field(&b, "DataSource", "true")
	}
	if r.NoResource {
		field(&b, "NoResource", "true")
	}
	if r.ReleaseOnDestroy {
		field(&b, "ReleaseOnDestroy", "true")
	}
	if r.FixedID != "" {
		field(&b, "FixedID", strconv.Quote(r.FixedID))
	}
	b.WriteString("Attrs: ")
	attrs(&b, r.Attrs)
	b.WriteString(",\n}\n}\n")
	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("formatting %s: %w\n%s", r.TypeName, err, b.String())
	}
	return out, nil
}

var pagingNames = map[engine.Paging]string{
	engine.PagingNumber: "engine.PagingNumber",
	engine.PagingFlat:   "engine.PagingFlat",
	engine.PagingCursor: "engine.PagingCursor",
}

// opLiteral renders an operation as a Go literal.
func opLiteral(o *engine.Op) string {
	s := fmt.Sprintf("&engine.Op{Method: %q, Path: %q, Envelope: %t", o.Method, o.Path, o.Envelope)
	if o.Paging != engine.PagingNone {
		s += fmt.Sprintf(", Paging: %s, PageSize: %d", pagingNames[o.Paging], o.PageSize)
	}
	return s + "}"
}

// EmitList renders one list descriptor as a Go source file.
func EmitList(pkg string, l *engine.List, source string) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s\n// Source: %s\n\n", Marker, source)
	fmt.Fprintf(&b, "package %s\n\n", pkg)
	b.WriteString("import \"github.com/RomansWorks/terraform-provider-telnyx/internal/engine\"\n\n")
	name := GoName(l.TypeName) + "List"
	fmt.Fprintf(&b, "// %s returns the list descriptor of %s.\n", name, l.TypeName)
	fmt.Fprintf(&b, "func %s() *engine.List {\n\treturn &engine.List{\n", name)
	field(&b, "TypeName", strconv.Quote(l.TypeName))
	field(&b, "Description", strconv.Quote(l.Description))
	field(&b, "Op", opLiteral(l.Op))
	b.WriteString("Params: ")
	attrs(&b, l.Params)
	b.WriteString(",\nItems: &engine.Attr")
	attr(&b, l.Items)
	b.WriteString(",\n}\n}\n")
	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("formatting %s: %w\n%s", l.TypeName, err, b.String())
	}
	return out, nil
}

// EmitAction renders one action descriptor as a Go source file.
func EmitAction(pkg string, a *engine.Action, source string) ([]byte, error) {
	return emitOne(pkg, a.TypeName, "Action", source, func(b *bytes.Buffer) {
		field(b, "TypeName", strconv.Quote(a.TypeName))
		field(b, "Description", strconv.Quote(a.Description))
		field(b, "Op", opLiteral(a.Op))
		b.WriteString("Attrs: ")
		attrs(b, a.Attrs)
		b.WriteString(",\n")
	})
}

// EmitEphemeral renders one ephemeral resource descriptor as a Go source
// file.
func EmitEphemeral(pkg string, e *engine.Ephemeral, source string) ([]byte, error) {
	return emitOne(pkg, e.TypeName, "Ephemeral", source, func(b *bytes.Buffer) {
		field(b, "TypeName", strconv.Quote(e.TypeName))
		field(b, "Description", strconv.Quote(e.Description))
		field(b, "Open", opLiteral(e.Open))
		b.WriteString("Attrs: ")
		attrs(b, e.Attrs)
		b.WriteString(",\n")
	})
}

// emitOne renders a file with one constructor, GoName(typeName)+kind,
// returning *engine.<kind> filled by body.
func emitOne(pkg, typeName, kind, source string, body func(*bytes.Buffer)) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s\n// Source: %s\n\n", Marker, source)
	fmt.Fprintf(&b, "package %s\n\n", pkg)
	b.WriteString("import \"github.com/RomansWorks/terraform-provider-telnyx/internal/engine\"\n\n")
	name := GoName(typeName) + kind
	fmt.Fprintf(&b, "// %s returns the %s descriptor of %s.\n", name, strings.ToLower(kind), typeName)
	fmt.Fprintf(&b, "func %s() *engine.%s {\n\treturn &engine.%s{\n", name, kind, kind)
	body(&b)
	b.WriteString("}\n}\n")
	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("formatting %s: %w\n%s", typeName, err, b.String())
	}
	return out, nil
}

func field(b *bytes.Buffer, name, value string) {
	fmt.Fprintf(b, "%s: %s,\n", name, value)
}

func quoteList(xs []string) string {
	q := make([]string, len(xs))
	for i, x := range xs {
		q[i] = strconv.Quote(x)
	}
	return "[]string{" + strings.Join(q, ", ") + "}"
}

func attrs(b *bytes.Buffer, as []*engine.Attr) {
	b.WriteString("[]*engine.Attr{\n")
	for _, a := range as {
		attr(b, a)
		b.WriteString(",\n")
	}
	b.WriteString("}")
}

func attr(b *bytes.Buffer, a *engine.Attr) {
	b.WriteString("{")
	var parts []string
	add := func(name, value string) { parts = append(parts, name+": "+value) }
	if a.Name != "" {
		add("Name", strconv.Quote(a.Name))
	}
	if a.JSON != "" {
		add("JSON", strconv.Quote(a.JSON))
	}
	add("Kind", kindNames[a.Kind])
	flags := []struct {
		name string
		on   bool
	}{
		{"Required", a.Required}, {"Optional", a.Optional}, {"Computed", a.Computed},
		{"Sensitive", a.Sensitive}, {"ForceNew", a.ForceNew},
		{"InCreate", a.InCreate}, {"InUpdate", a.InUpdate}, {"InResponse", a.InResponse}, {"Local", a.Local},
		{"WriteOnly", a.WriteOnly},
	}
	for _, f := range flags {
		if f.on {
			add(f.name, "true")
		}
	}
	if len(a.Enum) > 0 {
		add("Enum", quoteList(a.Enum))
	}
	if len(a.PathParams) > 0 {
		add("PathParams", quoteList(a.PathParams))
	}
	if a.Deprecated != "" {
		add("Deprecated", strconv.Quote(a.Deprecated))
	}
	if a.Version != "" {
		add("Version", strconv.Quote(a.Version))
	}
	if a.Description != "" {
		add("Description", strconv.Quote(a.Description))
	}
	b.WriteString(strings.Join(parts, ", "))
	if a.Elem != nil {
		b.WriteString(", Elem: &engine.Attr")
		attr(b, a.Elem)
	}
	if len(a.Attrs) > 0 {
		b.WriteString(",\nAttrs: ")
		attrs(b, a.Attrs)
	}
	b.WriteString("}")
}

// Generated is everything Run derives.
type Generated struct {
	Resources  []*engine.Resource
	Lists      []*engine.List
	Actions    []*engine.Action
	Ephemerals []*engine.Ephemeral
}

// EmitAll renders the file listing every generated descriptor.
func EmitAll(pkg string, gen *Generated) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, "%s\n\npackage %s\n\n", Marker, pkg)
	b.WriteString("import \"github.com/RomansWorks/terraform-provider-telnyx/internal/engine\"\n\n")
	listing := func(comment, fn, typ, suffix string, typeNames []string) {
		names := make([]string, len(typeNames))
		for i, n := range typeNames {
			names[i] = GoName(n) + suffix
		}
		sort.Strings(names)
		fmt.Fprintf(&b, "// %s\nfunc %s() []*engine.%s {\n\treturn []*engine.%s{\n", comment, fn, typ, typ)
		for _, n := range names {
			fmt.Fprintf(&b, "%s(),\n", n)
		}
		b.WriteString("}\n}\n\n")
	}
	var rs, ls, as, es []string
	for _, r := range gen.Resources {
		rs = append(rs, r.TypeName)
	}
	for _, l := range gen.Lists {
		ls = append(ls, l.TypeName)
	}
	for _, a := range gen.Actions {
		as = append(as, a.TypeName)
	}
	for _, e := range gen.Ephemerals {
		es = append(es, e.TypeName)
	}
	listing("All returns a fresh copy of every generated descriptor.", "All", "Resource", "", rs)
	listing("Lists returns a fresh copy of every generated list descriptor.", "Lists", "List", "List", ls)
	listing("Actions returns a fresh copy of every generated action descriptor.", "Actions", "Action", "Action", as)
	listing("Ephemerals returns a fresh copy of every generated ephemeral resource descriptor.", "Ephemerals", "Ephemeral", "Ephemeral", es)
	return format.Source(b.Bytes())
}

// FileName returns the generated file name for a type.
func FileName(typeName string) string {
	return strings.TrimPrefix(typeName, "telnyx_") + ".go"
}

// Write writes files into dir, leaving unchanged files untouched, and
// removes generated files that are no longer produced.
func Write(dir string, files map[string][]byte) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	existing, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		return err
	}
	for _, f := range existing {
		if _, keep := files[filepath.Base(f)]; keep {
			continue
		}
		data, err := os.ReadFile(f)
		if err != nil {
			return err
		}
		if bytes.HasPrefix(data, []byte(Marker)) {
			if err := os.Remove(f); err != nil {
				return err
			}
		}
	}
	for name, data := range files {
		p := filepath.Join(dir, name)
		if old, err := os.ReadFile(p); err == nil && bytes.Equal(old, data) {
			continue
		}
		if err := os.WriteFile(p, data, 0o644); err != nil {
			return err
		}
	}
	return nil
}

// Run derives every override in overridesDir and writes the descriptors
// into outDir as package pkg.
func Run(g *Generator, overridesDir, outDir, pkg string) (*Generated, error) {
	ovs, loadErr := LoadOverrides(overridesDir)
	files := map[string][]byte{}
	gen := &Generated{}

	add := func(name string, src []byte, err error) error {
		if err != nil {
			return err
		}
		if _, dup := files[name]; dup {
			return fmt.Errorf("two descriptors would be written to %s", name)
		}
		files[name] = src
		return nil
	}
	base := func(typeName string) string { return strings.TrimSuffix(FileName(typeName), ".go") }
	one := func(ov *Override) error {
		source := filepath.ToSlash(ov.file)
		switch ov.Kind {
		case "action":
			a, err := g.DeriveAction(ov)
			if err != nil {
				return err
			}
			src, err := EmitAction(pkg, a, source)
			if err := add(base(a.TypeName)+"_action.go", src, err); err != nil {
				return err
			}
			gen.Actions = append(gen.Actions, a)
			return nil
		case "ephemeral":
			e, err := g.DeriveEphemeral(ov)
			if err != nil {
				return err
			}
			src, err := EmitEphemeral(pkg, e, source)
			if err := add(base(e.TypeName)+"_ephemeral.go", src, err); err != nil {
				return err
			}
			gen.Ephemerals = append(gen.Ephemerals, e)
			return nil
		}
		r, l, err := g.DeriveAll(ov)
		if err != nil {
			return err
		}
		if r != nil {
			src, err := EmitResource(pkg, r, source)
			if err := add(FileName(r.TypeName), src, err); err != nil {
				return err
			}
			gen.Resources = append(gen.Resources, r)
		}
		if l != nil {
			src, err := EmitList(pkg, l, source)
			if err := add(base(l.TypeName)+"_list.go", src, err); err != nil {
				return err
			}
			gen.Lists = append(gen.Lists, l)
		}
		return nil
	}
	// Every override is derived, so one run reports every broken override.
	errs := []error{loadErr}
	for _, ov := range ovs {
		if err := one(ov); err != nil {
			errs = append(errs, err)
		}
	}
	if err := errors.Join(errs...); err != nil {
		return nil, err
	}
	all, err := EmitAll(pkg, gen)
	if err != nil {
		return nil, err
	}
	files["all.go"] = all
	return gen, Write(outDir, files)
}
